pub fn prompt_definition(id: PromptId) -> &'static PromptDefinition {
    let index = match id {
        PromptId::ProblemEnrichment => 0,
        PromptId::WorkflowDraftCapture => 1,
        PromptId::WorkflowDraftProblem => 2,
        PromptId::WorkflowRefinement => 3,
        PromptId::ImageSummary => 4,
        PromptId::CompletionReview => 5,
        PromptId::WorkbenchOrganization => 6,
        PromptId::KnowledgeTranslation => 7,
        PromptId::DerivedTranslation => 8,
        PromptId::LineageInference => 9,
        PromptId::TaskJourney => 10,
        PromptId::RefinementResponse => 11,
        PromptId::RefinementPreview => 12,
        PromptId::ConflictReview => 13,
        PromptId::KnowledgeDraft => 14,
        PromptId::CompletionReport => 15,
        _ => unreachable!("foundation prompt routed to current registry"),
    };
    &DEFINITIONS[index]
}
